INSERT INTO "chemicalRecipes" ("id","slug","name","groupName","baseVolume","baseUnit","stock","note","ingredients","method","active","status") VALUES (19,'icc-permeabilization','Permeabilization ICC','Dung dịch nhuộm ICC','100.000000','mL','Chọn PBS Tween 20 0,2% hoặc PBS Triton X-100 0,1%','Bảng người dùng cung cấp chưa nêu nồng độ stock và thể tích stock; cần hoàn thiện theo SOP phòng thí nghiệm trước khi pha số lượng lớn.','[{"form":"Lỏng","name":"PBS Tween 20 0,2%","note":"Lựa chọn 1 trong 2 cách pha permeabilization"},{"form":"Lỏng","name":"PBS Triton X-100 0,1%","note":"Lựa chọn 1 trong 2 cách pha permeabilization"}]','Chọn một trong hai hệ PBS Tween 20 0,2% hoặc PBS Triton X-100 0,1%
